-- INSERT OR IGNORE throughout.

-- ==================== es ====================

INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'es', 'Facturación numerada preautorizada (CAE) con transmisión electrónica obligatoria a la DGI -- implementada por fases según el nivel de facturación del contribuyente desde 2012, y universal para los contribuyentes de IVA desde el 1 de enero de 2025', 'Esta página de análisis refleja la orientación pública de la DGI y la información del sector disponible a principios de agosto de 2026, y se ofrece a título informativo general, no como asesoramiento legal o fiscal. Confirme los requisitos vigentes directamente con la DGI o con un asesor fiscal uruguayo antes de basar en esta página sus decisiones de cumplimiento.', 'El régimen de CFE de Uruguay comenzó con el Decreto 36/012 en 2012, implementó la adopción obligatoria por fases según el nivel de facturación del contribuyente entre 2014 y 2019, y cerró su ventana de exención restante el 1 de enero de 2025, cuando prácticamente todos los contribuyentes de IVA pasaron a ser emisores electrónicos obligatorios. La DGI sigue haciendo evolucionar el esquema técnico subyacente, más recientemente con nuevos controles de validación obligatorios en 2026.', 'Un CFE se genera como un documento XML firmado digitalmente, utilizando un rango numerado (CAE) que la DGI ha preautorizado al emisor, y se transmite a la DGI para su validación estructural y de formato antes de entregarse al destinatario con un código QR de verificación. Esto se entiende mejor como una numeración preautorizada con validación obligatoria posterior a la transmisión -- la DGI no aprueba cada factura individual en tiempo real antes de que llegue al comprador, pero cada CFE debe igualmente llegar a la DGI y superar sus controles para ser un documento tributario válido.', 'El mandato se ha ampliado por etapas: un proyecto piloto voluntario y un fundamento legal (2012), un despliegue plurianual por fases según el nivel de facturación del contribuyente (2014-2019), y un plazo final (Resolución 2548/023) que cerró la ventana de exención para prácticamente todos los contribuyentes de IVA restantes el 1 de enero de 2025. Queda una lista breve y definida de exenciones -- vea la tarjeta de alcance dedicada más abajo para saber exactamente quién sigue excluido.', 'La mayoría de las empresas que leen esto probablemente ya están obligadas a emitir CFE, dado cuánto tiempo lleva vigente el mandato de Uruguay -- el trabajo real y actual suele consistir en mantener el cumplimiento a medida que la DGI hace evolucionar el esquema técnico, no en un despliegue por primera vez.', 'Uruguay no establece un esquema de multas específico para el CFE -- el propio Decreto 36/012 indica que el incumplimiento se sanciona bajo el régimen general del Código Tributario, no mediante una tabla de sanciones dedicada a la facturación electrónica. Esto significa que la exposición real pasa por las disposiciones ordinarias del procedimiento tributario: incumplimiento formal, multas por impuesto omitido y -- en caso de dolo genuino -- responsabilidad penal por fraude.', 'Uruguay exige la emisión de CFE (Comprobante Fiscal Electrónico) mediante rangos numerados preautorizados por la DGI, con transmisión y validación electrónica obligatorias, para prácticamente todos los contribuyentes de IVA. Vigente en alguna forma desde 2012 y universal desde el 1 de enero de 2025, es uno de los regímenes de facturación electrónica más maduros de América Latina -- la DGI informó que el sistema ya cubría el 98% de la documentación emitida a nivel nacional cuando se cerró la ventana de exención.', '🇺🇾' FROM countries WHERE name_en = 'Uruguay';

INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'es', '1 ene 2025', 'Emisión obligatoria universal del CFE para todos los contribuyentes de IVA' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.name_en = 'Uruguay' AND s.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'es', '98%', 'De la documentación ya electrónica, según el propio anuncio de la DGI (nov. 2024)' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.name_en = 'Uruguay' AND s.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'es', '2012', 'Año en que la DGI creó el régimen de CFE (Decreto 36/012)' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.name_en = 'Uruguay' AND s.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'es', '2 años', 'Período de validez de un rango de numeración de CFE autorizado por la DGI (CAE)' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.name_en = 'Uruguay' AND s.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'es', 'Art. 110', 'Disposición del Código Tributario que tipifica el fraude fiscal (6 meses a 6 años)' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.name_en = 'Uruguay' AND s.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'es', 'Formato y transmisión', '[["Formato de factura", "XML, firmado digitalmente con un certificado electrónico acreditado"], ["Numeración/autorización", "CAE (Constancia de Autorización de Emisión) -- un bloque preautorizado de números correlativos, solicitado en lotes de al menos 100, válido por dos años"], ["Transmisión", "Cada CFE se envía a la DGI para su validación estructural/de formato y luego se entrega al destinatario"], ["Confirmación", "La aceptación de la DGI es un procesamiento asíncrono, no una determinación tributaria definitiva -- los documentos siguen sujetos a una auditoría posterior"]]', 'El CFE de Uruguay se entiende mejor como una numeración preautorizada con validación obligatoria posterior a la transmisión -- no es un control de clearance estricto factura por factura como el CFDI de México, pero tampoco un simple informe posterior a los hechos.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Uruguay' AND cd.section = 'file_format' AND cd.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'es', 'Código QR y tipos de documento', '[["Código QR", "Obligatorio en las representaciones impresas/PDF, con enlace a la herramienta pública de verificación de CFE de la DGI"], ["Tipos de documento principales", "e-Factura (B2B), e-Ticket (B2C/minorista), e-Factura de Exportación, e-Remito (guía de remisión), e-Resguardo (comprobante de retención), además de notas de crédito/débito para cada uno"], ["Contingencia", "CFC (Comprobante Fiscal Contingencia), utilizado cuando el sistema principal o la conectividad no están disponibles"], ["Verificación", "La propia herramienta en línea de la DGI permite a cualquier destinatario comprobar directamente la autenticidad de un CFE"]]', 'Confirme que su software de facturación realmente genera el tipo específico de CFE que requiere su transacción -- emitir un e-Ticket donde se necesitaba una e-Factura, o viceversa, genera fricciones reales de cumplimiento.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Uruguay' AND cd.section = 'file_format' AND cd.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'es', 'Base legal y versión del esquema', '[["Decreto fundacional", "Decreto 36/012 (8 de febrero de 2012)"], ["Marco operativo", "Resolución DGI 798/012 (8 de mayo de 2012)"], ["Versión actual del esquema", "Formato CFE v25 / v25.1, según la especificación técnica publicada por la DGI"], ["Referencia sancionatoria", "Decreto 36/012, Art. 17 -- aplica el régimen general de sanciones por documentación tributaria de Uruguay, no un esquema de multas específico para el CFE"]]', NULL, NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Uruguay' AND cd.section = 'file_format' AND cd.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) SELECT lc.id, 'es', 'El flujo del CFE', 'Una factura conforme recorre esta secuencia bajo el régimen de CFE de la DGI:', 'No se trata de un control de clearance estricto factura por factura -- la DGI preautoriza la numeración, no cada documento individual en tiempo real -- pero cada CFE debe igualmente llegar a la DGI y superar sus controles para ser un documento tributario válido.' FROM deep_dive_lifecycle_cards lc JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Uruguay';
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT st.id, 'es', 'El emisor solicita a la DGI un rango numerado (CAE), válido por dos años' FROM deep_dive_lifecycle_statuses_v2 st JOIN deep_dive_lifecycle_cards lc ON st.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Uruguay' AND st.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT st.id, 'es', 'La factura se genera como XML firmado, utilizando un número autorizado de ese rango' FROM deep_dive_lifecycle_statuses_v2 st JOIN deep_dive_lifecycle_cards lc ON st.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Uruguay' AND st.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT st.id, 'es', 'El CFE se transmite a la DGI, que realiza la validación estructural/de formato' FROM deep_dive_lifecycle_statuses_v2 st JOIN deep_dive_lifecycle_cards lc ON st.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Uruguay' AND st.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT st.id, 'es', 'El CFE se entrega al destinatario, con un código QR para verificación pública' FROM deep_dive_lifecycle_statuses_v2 st JOIN deep_dive_lifecycle_cards lc ON st.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Uruguay' AND st.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT st.id, 'es', 'El documento sigue sujeto a la revisión posterior de consistencia y auditoría de la DGI' FROM deep_dive_lifecycle_statuses_v2 st JOIN deep_dive_lifecycle_cards lc ON st.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Uruguay' AND st.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'es', 'Lo que exige la ley', '[["Decreto 36/012 (2012)", "Decreto fundacional que crea el régimen de CFE"], ["Resolución 798/012 (2012)", "Marco técnico/operativo"], ["Despliegue por fases según nivel de facturación (2014-2019)", "Primero los grandes contribuyentes, con contribuyentes más pequeños incorporados en olas anuales posteriores"], ["Resolución 2548/023 (2023)", "Fijó el plazo final del 31 de diciembre de 2024 para la población de contribuyentes restante"]]', 'Esta es la cronología legal -- vea la siguiente tarjeta para saber exactamente quién está comprendido a partir del mandato universal de enero de 2025.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Uruguay' AND cd.section = 'scope_transmission' AND cd.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'es', 'Quién sigue exento tras el mandato universal de enero de 2025', '[["Pequeña agricultura", "Actividad exclusivamente agropecuaria, ingresos anuales inferiores a UI 4.000.000"], ["Construcción con valor agregado", "Contribuyentes de IVA que solo prestan servicios de construcción con valor agregado sobre inmuebles"], ["Contribuyentes de IRNR", "Contribuyentes del impuesto a la renta de no residentes"], ["Actividad totalmente exenta de IVA", "Salvo los usuarios directos/indirectos de zonas francas, que permanecen dentro del alcance"], ["Regímenes simplificados de microempresas", "Participantes de Monotributo, Monotributo Social MIDES y Aporte Único"]]', 'Esta lista refleja el propio anuncio de la DGI del 28 de noviembre de 2024 -- si no está seguro de si una exención todavía se aplica a su empresa, confírmelo directamente con la DGI en lugar de asumir que una excepción anterior sobrevivió al cierre de enero de 2025.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Uruguay' AND cd.section = 'scope_transmission' AND cd.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'es', '⚖️ Uruguay no establece multas específicas para el CFE', NULL, NULL, 'El Decreto 36/012, Art. 17, establece explícitamente que el incumplimiento del CFE se sanciona bajo el régimen general de sanciones por documentación tributaria de Uruguay, y no mediante un esquema de multas dedicado a la facturación electrónica. Ese régimen se encuentra en el Código Tributario (Ley 14.306, 1974) -- las disposiciones que figuran a continuación son las que realmente rigen la exposición, no las cifras redondas en pesos que a veces circulan en contenido de proveedores, y que esta página deliberadamente no repite porque no pudieron rastrearse hasta una fuente verificable.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Uruguay' AND cd.section = 'penalties_related' AND cd.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'es', '📋 Incumplimiento formal e impuesto omitido', NULL, NULL, 'El artículo 95 del Código Tributario regula la ''contravención'' -- la violación de deberes formales, incluido el deber de emitir el CFE correctamente -- con una multa fijada en el propio texto del código; no pudo confirmarse de forma independiente si esa cifra ha sido actualizada administrativamente desde que se redactó la ley en 1974, por lo que conviene tratar con cautela cualquier importe específico en pesos citado en otras fuentes. Por separado, el artículo 97 aborda la ''omisión de pago'': cuando las irregularidades del CFE derivan en una liquidación insuficiente de IVA o IRAE, la multa es de una a cinco veces el importe omitido.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Uruguay' AND cd.section = 'penalties_related' AND cd.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'es', '🔒 Consecuencias prácticas más allá de una multa', NULL, NULL, 'Un CFE rechazado o que nunca se emitió correctamente se trata como si no existiera factura alguna -- el destinatario pierde la posibilidad de deducir el gasto o de reclamar el crédito de IVA asociado. Varias fuentes de la práctica profesional también vinculan el incumplimiento grave o reiterado con el riesgo de que la DGI suspenda el Certificado Único del contribuyente, el certificado general de estar al día con las obligaciones tributarias requerido para contratar con el Estado, obtener crédito bancario y realizar muchas transacciones comerciales -- aunque no pudo confirmarse una única norma codificada que establezca que una falla del CFE desencadene automáticamente esa suspensión, por lo que conviene tratarlo como un riesgo práctico real más que como una consecuencia legal automática.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Uruguay' AND cd.section = 'penalties_related' AND cd.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'es', '🚨 El fraude basado en el dolo es un delito penal', NULL, NULL, 'El artículo 110 del Código Tributario tipifica la ''defraudación tributaria'' -- el uso de engaño para obtener un beneficio indebido a costa del Estado -- como delito penal, sancionado con pena de seis meses a seis años de prisión. Su persecución requiere que la propia DGI presente una denuncia formal y fundada; está reservada para los casos de fraude genuino, no para el incumplimiento formal habitual.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Uruguay' AND cd.section = 'penalties_related' AND cd.sort_order = 3;

INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT pr.id, 'es', 'Incumplimiento formal de los deberes de emisión del CFE (Código Tributario, Art. 95 -- ''contravención'')', 'Una multa fijada según el régimen general de contravención del Art. 95 -- confirme el importe actualmente aplicable con la DGI o con un asesor fiscal uruguayo en lugar de basarse en una cifra sin verificar', '—' FROM deep_dive_penalty_rows pr JOIN countries c ON pr.country_id = c.id WHERE c.name_en = 'Uruguay' AND pr.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT pr.id, 'es', 'Liquidación insuficiente de IVA/IRAE derivada de irregularidades del CFE (Código Tributario, Art. 97 -- ''omisión de pago'')', 'De 1 a 5 veces el importe del impuesto omitido', '—' FROM deep_dive_penalty_rows pr JOIN countries c ON pr.country_id = c.id WHERE c.name_en = 'Uruguay' AND pr.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT pr.id, 'es', 'Fraude fiscal basado en dolo (Código Tributario, Art. 110 -- ''defraudación tributaria'')', 'De 6 meses a 6 años de prisión; requiere una denuncia formal de la DGI', '—' FROM deep_dive_penalty_rows pr JOIN countries c ON pr.country_id = c.id WHERE c.name_en = 'Uruguay' AND pr.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'es', 'Confirme si su empresa ya está obligada a emitir CFE', 'Compruebe si quedó comprendida en una ola anterior por nivel de facturación (2014-2019) o si solo entró en el alcance con el mandato universal de enero de 2025 -- y confirme que no se encuentra dentro de una de las escasas exenciones restantes.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Uruguay' AND sp.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'es', 'Regístrese ante la DGI como emisor electrónico y obtenga un certificado válido', 'Necesitará un certificado electrónico acreditado para firmar los CFE, y deberá solicitar a la DGI su primer rango numerado (CAE) antes de poder emitir documentos conformes.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Uruguay' AND sp.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'es', 'Elija el tipo de CFE adecuado para cada transacción', 'Utilice e-Factura para las ventas B2B, e-Ticket para el comercio minorista/B2C, y los tipos de documento correspondientes de exportación, guía de remisión o retención cuando corresponda -- emitir el tipo equivocado genera fricciones reales de cumplimiento.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Uruguay' AND sp.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'es', 'Integre en su sistema de facturación la generación de XML, la firma digital y la transmisión a la DGI', 'Confirme que su software realmente genera un XML de CFE conforme y firmado, y lo transmite a la DGI -- no dependa de un proceso manual o por lotes que pueda quedar rezagado respecto de los requisitos de numeración y validación de la DGI.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Uruguay' AND sp.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'es', 'Controle su rango de CAE y solicite uno nuevo antes de que se agote', 'Un rango de CAE es válido por dos años y debe solicitarse en lotes de al menos 100 números -- agotarlo en plena operación le impediría emitir facturas conformes.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Uruguay' AND sp.sort_order = 4;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'es', 'Confirme que su software o proveedor está certificado para la versión actual del esquema del CFE', 'La DGI revisa periódicamente la especificación técnica del CFE -- más recientemente hasta la v25.1, con nuevos controles obligatorios a partir del 15 de abril de 2026 -- por lo que conviene preguntar directamente a su proveedor en lugar de asumir la compatibilidad continuada.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Uruguay' AND sp.sort_order = 5;

INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT pt.id, 'es', 'DGI e-Factura — el portal oficial del CFE, especificaciones técnicas y herramienta pública de verificación de facturas' FROM deep_dive_portals pt JOIN countries c ON pt.country_id = c.id WHERE c.name_en = 'Uruguay' AND pt.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT pt.id, 'es', 'Dirección General Impositiva (DGI) — página institucional sobre Facturación Electrónica, anuncios y resoluciones oficiales' FROM deep_dive_portals pt JOIN countries c ON pt.country_id = c.id WHERE c.name_en = 'Uruguay' AND pt.sort_order = 1;

-- ==================== de ====================

INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'de', 'Vorautorisierte nummerierte Rechnungsstellung (CAE) mit verpflichtender elektronischer Übermittlung an die DGI -- seit 2012 stufenweise nach Umsatzklasse des Steuerpflichtigen eingeführt und seit dem 1. Januar 2025 universell für umsatzsteuerpflichtige Personen', 'Diese Analyseseite spiegelt öffentlich verfügbare Hinweise der DGI und Brancheninformationen mit Stand Anfang August 2026 wider und dient allgemeinen Informationszwecken, nicht als Rechts- oder Steuerberatung. Bestätigen Sie aktuelle Anforderungen direkt bei der DGI oder einem uruguayischen Steuerberater, bevor Sie sich bei Compliance-Entscheidungen auf diese Seite verlassen.', 'Uruguays CFE-Regime begann 2012 mit dem Decreto 36/012, führte die verpflichtende Einführung von 2014 bis 2019 stufenweise nach Umsatzklasse des Steuerpflichtigen ein und schloss sein verbleibendes Ausnahmefenster am 1. Januar 2025, als praktisch alle umsatzsteuerpflichtigen Personen zu verpflichteten elektronischen Rechnungsstellern wurden. Die DGI entwickelt das zugrunde liegende technische Schema weiter, zuletzt mit neuen verpflichtenden Validierungskontrollen im Jahr 2026.', 'Ein CFE wird als digital signiertes XML-Dokument erstellt, unter Verwendung eines nummerierten Bereichs (CAE), den die DGI dem Aussteller vorab genehmigt hat, und zur strukturellen und formalen Validierung an die DGI übermittelt, bevor er dem Empfänger mit einem Prüf-QR-Code zugestellt wird. Man versteht dies am besten als vorautorisierte Nummerierung mit verpflichtender Validierung nach der Übermittlung -- die DGI genehmigt nicht jede einzelne Rechnung in Echtzeit, bevor sie den Käufer erreicht, aber jeder CFE muss dennoch die DGI erreichen und deren Prüfungen bestehen, um ein gültiges Steuerdokument zu sein.', 'Die Pflicht hat sich stufenweise ausgeweitet: ein freiwilliges Pilotprojekt und die rechtliche Grundlage (2012), ein mehrjähriger stufenweiser Rollout nach Umsatzklasse des Steuerpflichtigen (2014-2019) und eine endgültige Frist (Resolución 2548/023), die das Ausnahmefenster für praktisch alle verbleibenden umsatzsteuerpflichtigen Personen am 1. Januar 2025 schloss. Eine kurze, klar definierte Liste von Ausnahmen bleibt bestehen -- siehe die eigene Karte zum Anwendungsbereich weiter unten, wer genau noch ausgenommen ist.', 'Die meisten Unternehmen, die dies lesen, sind angesichts der langen Geltungsdauer der uruguayischen Pflicht wahrscheinlich bereits zur CFE-Ausstellung verpflichtet -- die eigentliche, aktuelle Aufgabe besteht in der Regel darin, die Einhaltung aufrechtzuerhalten, während die DGI das technische Schema weiterentwickelt, nicht in einer erstmaligen Einführung.', 'Uruguay legt keinen eigenen CFE-Bußgeldkatalog fest -- der Decreto 36/012 selbst besagt, dass Verstöße nach dem allgemeinen Código-Tributario-Regime geahndet werden, nicht nach einer eigenen Strafentabelle für die E-Rechnungsstellung. Das bedeutet, dass das tatsächliche Risiko über die gewöhnlichen steuerverfahrensrechtlichen Bestimmungen läuft: formale Verstöße, Bußgelder für zu niedrig angegebene Steuern und -- bei echtem Betrug -- strafrechtliche Haftung.', 'Uruguay verlangt die Ausstellung von CFE (Comprobante Fiscal Electrónico) über von der DGI vorautorisierte nummerierte Bereiche, mit verpflichtender elektronischer Übermittlung und Validierung, für praktisch alle umsatzsteuerpflichtigen Personen. Seit 2012 in irgendeiner Form in Kraft und seit dem 1. Januar 2025 universell, ist es eines der ausgereiftesten E-Invoicing-Regime Lateinamerikas -- die DGI berichtete, dass das System bereits 98 % der landesweit ausgestellten Dokumentation abdeckte, als das Ausnahmefenster geschlossen wurde.', '🇺🇾' FROM countries WHERE name_en = 'Uruguay';

INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'de', '1. Jan. 2025', 'Universelle verpflichtende CFE-Ausstellung für alle umsatzsteuerpflichtigen Personen' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.name_en = 'Uruguay' AND s.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'de', '98 %', 'Der Dokumentation bereits elektronisch, laut eigener Ankündigung der DGI (Nov. 2024)' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.name_en = 'Uruguay' AND s.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'de', '2012', 'Jahr, in dem die DGI das CFE-Regime schuf (Decreto 36/012)' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.name_en = 'Uruguay' AND s.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'de', '2 Jahre', 'Gültigkeitsdauer eines von der DGI genehmigten CFE-Nummernbereichs (CAE)' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.name_en = 'Uruguay' AND s.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'de', 'Art. 110', 'Bestimmung des Código Tributario, die Steuerbetrug unter Strafe stellt (6 Monate bis 6 Jahre)' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.name_en = 'Uruguay' AND s.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', 'Format & Übermittlung', '[["Rechnungsformat", "XML, digital signiert mit einem akkreditierten elektronischen Zertifikat"], ["Nummerierung/Genehmigung", "CAE (Constancia de Autorización de Emisión) -- ein vorautorisierter Block fortlaufender Nummern, beantragt in Losen von mindestens 100, zwei Jahre gültig"], ["Übermittlung", "Jeder CFE wird zur strukturellen/formalen Validierung an die DGI gesendet und anschließend dem Empfänger zugestellt"], ["Bestätigung", "Die Annahme durch die DGI ist eine asynchrone Verarbeitung, keine endgültige steuerliche Festsetzung -- Dokumente bleiben einer späteren Prüfung unterworfen"]]', 'Uruguays CFE versteht man am besten als vorautorisierte Nummerierung mit verpflichtender Validierung nach der Übermittlung -- keine strikte Freigabe pro Rechnung wie bei Mexikos CFDI, aber auch keine einfache nachträgliche Meldung.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Uruguay' AND cd.section = 'file_format' AND cd.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', 'QR-Code & Belegtypen', '[["QR-Code", "Auf gedruckten/PDF-Darstellungen erforderlich, mit Verweis auf das öffentliche CFE-Prüftool der DGI"], ["Wichtigste Belegtypen", "e-Factura (B2B), e-Ticket (B2C/Einzelhandel), e-Factura de Exportación, e-Remito (Lieferschein), e-Resguardo (Beleg über Quellensteuerabzug), zuzüglich Gutschriften/Lastschriften für jeden Typ"], ["Notfalllösung", "CFC (Comprobante Fiscal Contingencia), verwendet, wenn das primäre System oder die Konnektivität nicht verfügbar ist"], ["Prüfung", "Das eigene Online-Tool der DGI ermöglicht es jedem Empfänger, die Echtheit eines CFE direkt zu überprüfen"]]', 'Stellen Sie sicher, dass Ihre Rechnungssoftware tatsächlich den für Ihre Transaktion erforderlichen CFE-Typ erzeugt -- die Ausstellung eines e-Ticket, wo eine e-Factura erforderlich gewesen wäre, oder umgekehrt, führt zu echten Compliance-Problemen.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Uruguay' AND cd.section = 'file_format' AND cd.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', 'Rechtsgrundlage & Schemaversion', '[["Gründungserlass", "Decreto 36/012 (8. Februar 2012)"], ["Operatives Rahmenwerk", "Resolución DGI 798/012 (8. Mai 2012)"], ["Aktuelle Schemaversion", "CFE-Format v25 / v25.1, gemäß der veröffentlichten technischen Spezifikation der DGI"], ["Sanktionsverweis", "Decreto 36/012, Art. 17 -- wendet Uruguays allgemeines Sanktionsregime für steuerliche Dokumentation an, nicht einen eigenen CFE-Bußgeldkatalog"]]', NULL, NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Uruguay' AND cd.section = 'file_format' AND cd.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) SELECT lc.id, 'de', 'Der CFE-Ablauf', 'Eine konforme Rechnung durchläuft unter Uruguays CFE-Regime der DGI diese Abfolge:', 'Dies ist keine strikte Freigabe pro Rechnung -- die DGI genehmigt die Nummerierung vorab, nicht jedes einzelne Dokument in Echtzeit -- aber jeder CFE muss dennoch die DGI erreichen und deren Prüfungen bestehen, um ein gültiges Steuerdokument zu sein.' FROM deep_dive_lifecycle_cards lc JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Uruguay';
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT st.id, 'de', 'Der Aussteller beantragt bei der DGI einen nummerierten Bereich (CAE), zwei Jahre gültig' FROM deep_dive_lifecycle_statuses_v2 st JOIN deep_dive_lifecycle_cards lc ON st.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Uruguay' AND st.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT st.id, 'de', 'Die Rechnung wird als signiertes XML erstellt, unter Verwendung einer genehmigten Nummer aus diesem Bereich' FROM deep_dive_lifecycle_statuses_v2 st JOIN deep_dive_lifecycle_cards lc ON st.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Uruguay' AND st.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT st.id, 'de', 'Der CFE wird an die DGI übermittelt, die eine strukturelle/formale Validierung durchführt' FROM deep_dive_lifecycle_statuses_v2 st JOIN deep_dive_lifecycle_cards lc ON st.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Uruguay' AND st.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT st.id, 'de', 'Der CFE wird dem Empfänger mit einem QR-Code zur öffentlichen Prüfung zugestellt' FROM deep_dive_lifecycle_statuses_v2 st JOIN deep_dive_lifecycle_cards lc ON st.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Uruguay' AND st.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT st.id, 'de', 'Das Dokument bleibt der späteren Konsistenz- und Prüfungskontrolle der DGI unterworfen' FROM deep_dive_lifecycle_statuses_v2 st JOIN deep_dive_lifecycle_cards lc ON st.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Uruguay' AND st.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', 'Was das Gesetz verlangt', '[["Decreto 36/012 (2012)", "Gründungserlass zur Schaffung des CFE-Regimes"], ["Resolución 798/012 (2012)", "Technisches/operatives Rahmenwerk"], ["Stufenweiser Rollout nach Umsatzklasse (2014-2019)", "Zuerst Großsteuerpflichtige, kleinere Steuerpflichtige folgten in späteren jährlichen Wellen"], ["Resolución 2548/023 (2023)", "Legte die endgültige Frist vom 31. Dezember 2024 für die verbleibende Steuerpflichtigen-Gruppe fest"]]', 'Dies ist der rechtliche Zeitplan -- siehe die nächste Karte dazu, wer genau ab der universellen Pflicht vom Januar 2025 erfasst ist.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Uruguay' AND cd.section = 'scope_transmission' AND cd.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', 'Wer nach der universellen Pflicht vom Januar 2025 weiterhin ausgenommen ist', '[["Kleinlandwirtschaft", "Ausschließlich landwirtschaftliche Tätigkeit, Jahreseinkommen unter UI 4.000.000"], ["Wertschöpfende Bauleistungen", "Umsatzsteuerpflichtige, die ausschließlich wertschöpfende Bauleistungen an Immobilien erbringen"], ["IRNR-Steuerpflichtige", "Steuerpflichtige der Einkommensteuer für Gebietsfremde"], ["Vollständig umsatzsteuerbefreite Tätigkeit", "Außer für direkte/indirekte Nutzer von Freihandelszonen, die weiterhin erfasst bleiben"], ["Vereinfachte Kleinstunternehmerregime", "Teilnehmer von Monotributo, Monotributo Social MIDES und Aporte Único"]]', 'Diese Liste spiegelt die eigene Ankündigung der DGI vom 28. November 2024 wider -- wenn Sie nicht sicher sind, ob eine Ausnahme noch für Ihr Unternehmen gilt, bestätigen Sie dies direkt bei der DGI, statt anzunehmen, dass eine ältere Ausnahmeregelung die Schließung im Januar 2025 überdauert hat.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Uruguay' AND cd.section = 'scope_transmission' AND cd.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', '⚖️ Uruguay legt keine eigenen CFE-Bußgelder fest', NULL, NULL, 'Decreto 36/012, Art. 17 besagt ausdrücklich, dass CFE-Verstöße nach Uruguays allgemeinem Sanktionsregime für steuerliche Dokumentation geahndet werden, nicht nach einem eigenen Bußgeldkatalog für die E-Rechnungsstellung. Dieses Regime findet sich im Código Tributario (Ley 14.306, 1974) -- die untenstehenden Bestimmungen regeln das tatsächliche Risiko, nicht die runden Peso-Beträge, die gelegentlich in Anbieterinhalten kursieren und die diese Seite bewusst nicht wiederholt, weil sie sich nicht auf eine überprüfbare Quelle zurückführen ließen.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Uruguay' AND cd.section = 'penalties_related' AND cd.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', '📋 Formale Verstöße und zu niedrig angegebene Steuer', NULL, NULL, 'Artikel 95 des Código Tributario regelt die ''contravención'' -- die Verletzung formaler Pflichten, einschließlich der Pflicht zur korrekten CFE-Ausstellung -- mit einem im Gesetzestext festgelegten Bußgeld; ob dieser Betrag seit der Abfassung des Gesetzes von 1974 verwaltungsmäßig angepasst wurde, ließ sich nicht unabhängig bestätigen, weshalb konkrete, andernorts genannte Peso-Beträge mit Vorsicht zu behandeln sind. Separat regelt Artikel 97 die ''omisión de pago'': Führen CFE-Unregelmäßigkeiten zu einer zu niedrig angegebenen Umsatzsteuer- oder IRAE-Schuld, beträgt das Bußgeld das Ein- bis Fünffache des hinterzogenen Steuerbetrags.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Uruguay' AND cd.section = 'penalties_related' AND cd.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', '🔒 Praktische Folgen über ein Bußgeld hinaus', NULL, NULL, 'Ein CFE, der abgelehnt oder nie ordnungsgemäß ausgestellt wurde, wird so behandelt, als hätte keine Rechnung existiert -- der Empfänger verliert die Möglichkeit, die Ausgabe abzusetzen oder den zugehörigen Vorsteuerabzug geltend zu machen. Mehrere Praxisquellen bringen schwerwiegende oder wiederholte Verstöße zudem mit dem Risiko in Verbindung, dass die DGI das Certificado Único eines Steuerpflichtigen aussetzt -- die allgemeine Steuer-Compliance-Bescheinigung, die für öffentliche Aufträge, Bankkredite und viele Geschäftstransaktionen erforderlich ist -- wobei keine einzelne kodifizierte Regel bestätigt werden konnte, wonach ein CFE-Ausfall diese Aussetzung automatisch auslöst; behandeln Sie dies daher als reales praktisches Risiko, nicht als automatische rechtliche Folge.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Uruguay' AND cd.section = 'penalties_related' AND cd.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', '🚨 Betrug durch Täuschung ist eine Straftat', NULL, NULL, 'Artikel 110 des Código Tributario stellt die ''defraudación tributaria'' -- die Erlangung eines ungerechtfertigten Vorteils zulasten des Staates durch Täuschung -- als Straftat unter Strafe, die mit sechs Monaten bis sechs Jahren Freiheitsstrafe geahndet wird. Die strafrechtliche Verfolgung setzt voraus, dass die DGI selbst eine förmliche, begründete Anzeige erstattet; dies ist echtem Betrug vorbehalten, nicht routinemäßigen formalen Verstößen.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Uruguay' AND cd.section = 'penalties_related' AND cd.sort_order = 3;

INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT pr.id, 'de', 'Formaler Verstoß gegen die CFE-Ausstellungspflichten (Código Tributario, Art. 95 -- ''contravención'')', 'Ein Bußgeld nach dem allgemeinen Contravención-Katalog des Art. 95 -- bestätigen Sie den aktuell geltenden Betrag bei der DGI oder einem uruguayischen Steuerberater, statt sich auf eine unbestätigte Zahl zu verlassen', '—' FROM deep_dive_penalty_rows pr JOIN countries c ON pr.country_id = c.id WHERE c.name_en = 'Uruguay' AND pr.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT pr.id, 'de', 'Zu niedrig angegebene Umsatzsteuer-/IRAE-Schuld infolge von CFE-Unregelmäßigkeiten (Código Tributario, Art. 97 -- ''omisión de pago'')', '1- bis 5-facher Betrag der hinterzogenen Steuer', '—' FROM deep_dive_penalty_rows pr JOIN countries c ON pr.country_id = c.id WHERE c.name_en = 'Uruguay' AND pr.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT pr.id, 'de', 'Steuerbetrug durch Täuschung (Código Tributario, Art. 110 -- ''defraudación tributaria'')', '6 Monate bis 6 Jahre Freiheitsstrafe; erfordert eine förmliche Anzeige der DGI', '—' FROM deep_dive_penalty_rows pr JOIN countries c ON pr.country_id = c.id WHERE c.name_en = 'Uruguay' AND pr.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'de', 'Bestätigen Sie, ob Ihr Unternehmen bereits zur CFE-Ausstellung verpflichtet ist', 'Prüfen Sie, ob Sie von einer früheren Umsatzklassen-Welle (2014-2019) erfasst wurden oder erst mit der universellen Pflicht vom Januar 2025 in den Anwendungsbereich kamen -- und bestätigen Sie, dass Sie nicht unter eine der wenigen verbleibenden Ausnahmen fallen.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Uruguay' AND sp.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'de', 'Registrieren Sie sich bei der DGI als elektronischer Rechnungssteller und beschaffen Sie ein gültiges Zertifikat', 'Sie benötigen ein akkreditiertes elektronisches Zertifikat zur Signierung von CFE und müssen bei der DGI Ihren ersten nummerierten Bereich (CAE) beantragen, bevor Sie konforme Dokumente ausstellen können.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Uruguay' AND sp.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'de', 'Wählen Sie für jede Transaktion den richtigen CFE-Typ', 'Verwenden Sie e-Factura für B2B-Verkäufe, e-Ticket für den Einzelhandel/B2C sowie die entsprechenden Belegtypen für Export, Lieferschein oder Quellensteuer, wo zutreffend -- die Ausstellung des falschen Typs führt zu echten Compliance-Problemen.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Uruguay' AND sp.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'de', 'Integrieren Sie XML-Erstellung, digitale Signierung und DGI-Übermittlung in Ihr Rechnungssystem', 'Stellen Sie sicher, dass Ihre Software tatsächlich ein konformes, signiertes CFE-XML erzeugt und an die DGI übermittelt -- verlassen Sie sich nicht auf einen manuellen oder Batch-Prozess, der hinter die Nummerierungs- und Validierungsanforderungen der DGI zurückfallen könnte.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Uruguay' AND sp.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'de', 'Behalten Sie Ihren CAE-Bereich im Blick und beantragen Sie rechtzeitig einen neuen', 'Ein CAE-Bereich ist zwei Jahre gültig und muss in Losen von mindestens 100 Nummern beantragt werden -- geht er mitten im laufenden Betrieb zur Neige, könnten Sie keine konformen Rechnungen mehr ausstellen.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Uruguay' AND sp.sort_order = 4;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'de', 'Bestätigen Sie, dass Ihre Software oder Ihr Anbieter für die aktuelle CFE-Schemaversion zertifiziert ist', 'Die DGI überarbeitet die technische Spezifikation des CFE regelmäßig -- zuletzt auf v25.1, mit neuen verpflichtenden Kontrollen ab dem 15. April 2026 -- fragen Sie daher direkt bei Ihrem Anbieter nach, statt fortlaufende Kompatibilität anzunehmen.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Uruguay' AND sp.sort_order = 5;

INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT pt.id, 'de', 'DGI e-Factura — das offizielle CFE-Portal, technische Spezifikationen und öffentliches Rechnungsprüftool' FROM deep_dive_portals pt JOIN countries c ON pt.country_id = c.id WHERE c.name_en = 'Uruguay' AND pt.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT pt.id, 'de', 'Dirección General Impositiva (DGI) — institutionelle Seite zur Facturación Electrónica, offizielle Ankündigungen und Resolutionen' FROM deep_dive_portals pt JOIN countries c ON pt.country_id = c.id WHERE c.name_en = 'Uruguay' AND pt.sort_order = 1;

-- ==================== fr ====================

INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'fr', 'Facturation numérotée préautorisée (CAE) avec transmission électronique obligatoire à la DGI -- déployée par étapes selon la tranche de chiffre d''affaires du contribuable depuis 2012, et universelle pour les assujettis à la TVA depuis le 1er janvier 2025', 'Cette page d''analyse reflète les indications publiques de la DGI et les informations sectorielles disponibles début août 2026, et est fournie à titre d''information générale, non comme un conseil juridique ou fiscal. Confirmez les exigences actuelles directement auprès de la DGI ou d''un conseiller fiscal uruguayen avant de fonder vos décisions de conformité sur cette page.', 'Le régime CFE de l''Uruguay a débuté avec le Decreto 36/012 en 2012, a déployé par étapes l''adoption obligatoire selon la tranche de chiffre d''affaires du contribuable de 2014 à 2019, et a refermé sa fenêtre d''exemption restante le 1er janvier 2025, lorsque pratiquement tous les assujettis à la TVA sont devenus émetteurs électroniques obligatoires. La DGI continue de faire évoluer le schéma technique sous-jacent, le plus récemment avec de nouveaux contrôles de validation obligatoires en 2026.', 'Un CFE est généré sous la forme d''un document XML signé numériquement, à l''aide d''une plage numérotée (CAE) que la DGI a préautorisée à l''émetteur, et transmis à la DGI pour une validation structurelle et formelle avant d''être remis au destinataire avec un code QR de vérification. On comprend mieux ce système comme une numérotation préautorisée assortie d''une validation obligatoire post-transmission -- la DGI n''approuve pas chaque facture individuelle en temps réel avant qu''elle n''atteigne l''acheteur, mais chaque CFE doit néanmoins parvenir à la DGI et réussir ses contrôles pour constituer un document fiscal valable.', 'L''obligation s''est étendue par étapes : un projet pilote volontaire et un fondement légal (2012), un déploiement pluriannuel par étapes selon la tranche de chiffre d''affaires du contribuable (2014-2019), et une échéance finale (Resolución 2548/023) qui a refermé la fenêtre d''exemption pour pratiquement tous les assujettis à la TVA restants le 1er janvier 2025. Une courte liste définie d''exemptions subsiste -- voir la carte dédiée au champ d''application ci-dessous pour savoir précisément qui reste exclu.', 'La plupart des entreprises qui lisent ceci sont probablement déjà tenues d''émettre des CFE, étant donné depuis combien de temps l''obligation uruguayenne est en vigueur -- le travail réel et actuel consiste généralement à maintenir la conformité à mesure que la DGI fait évoluer le schéma technique, et non à réaliser un déploiement pour la première fois.', 'L''Uruguay ne fixe aucun barème d''amendes spécifique au CFE -- le Decreto 36/012 lui-même indique que le non-respect est sanctionné selon le régime général du Código Tributario, et non par un tableau de sanctions dédié à la facturation électronique. Cela signifie que l''exposition réelle relève des dispositions ordinaires de procédure fiscale : non-conformité formelle, amendes pour impôt sous-déclaré et -- en cas de dol véritable -- responsabilité pénale pour fraude.', 'L''Uruguay exige l''émission de CFE (Comprobante Fiscal Electrónico) via des plages numérotées préautorisées par la DGI, avec transmission et validation électroniques obligatoires, pour pratiquement tous les assujettis à la TVA. En vigueur sous une forme ou une autre depuis 2012 et universelle depuis le 1er janvier 2025, il s''agit de l''un des régimes de facturation électronique les plus matures d''Amérique latine -- la DGI a indiqué que le système couvrait déjà 98 % de la documentation émise à l''échelle nationale au moment de la fermeture de la fenêtre d''exemption.', '🇺🇾' FROM countries WHERE name_en = 'Uruguay';

INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'fr', '1er janv. 2025', 'Émission obligatoire universelle du CFE pour tous les assujettis à la TVA' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.name_en = 'Uruguay' AND s.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'fr', '98 %', 'De la documentation déjà électronique, selon l''annonce de la DGI elle-même (nov. 2024)' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.name_en = 'Uruguay' AND s.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'fr', '2012', 'Année où la DGI a créé le régime CFE (Decreto 36/012)' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.name_en = 'Uruguay' AND s.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'fr', '2 ans', 'Durée de validité d''une plage de numérotation CFE autorisée par la DGI (CAE)' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.name_en = 'Uruguay' AND s.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'fr', 'Art. 110', 'Disposition du Código Tributario qui érige la fraude fiscale en infraction pénale (6 mois à 6 ans)' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.name_en = 'Uruguay' AND s.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', 'Format et transmission', '[["Format de facture", "XML, signé numériquement au moyen d''un certificat électronique accrédité"], ["Numérotation/autorisation", "CAE (Constancia de Autorización de Emisión) -- un bloc préautorisé de numéros séquentiels, demandé par lots d''au moins 100, valable deux ans"], ["Transmission", "Chaque CFE est envoyé à la DGI pour validation structurelle/formelle, puis remis au destinataire"], ["Confirmation", "L''acceptation par la DGI relève d''un traitement asynchrone, non d''une détermination fiscale définitive -- les documents restent soumis à un contrôle ultérieur"]]', 'Le CFE uruguayen se comprend mieux comme une numérotation préautorisée assortie d''une validation obligatoire post-transmission -- ni un dédouanement strict facture par facture comme le CFDI mexicain, ni un simple rapport a posteriori.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Uruguay' AND cd.section = 'file_format' AND cd.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', 'Code QR et types de documents', '[["Code QR", "Obligatoire sur les représentations imprimées/PDF, renvoyant vers l''outil public de vérification des CFE de la DGI"], ["Principaux types de documents", "e-Factura (B2B), e-Ticket (B2C/commerce de détail), e-Factura de Exportación, e-Remito (bon de livraison), e-Resguardo (reçu de retenue à la source), plus les notes de crédit/débit pour chacun"], ["Solution de contingence", "CFC (Comprobante Fiscal Contingencia), utilisé lorsque le système principal ou la connectivité n''est pas disponible"], ["Vérification", "L''outil en ligne de la DGI permet à tout destinataire de vérifier directement l''authenticité d''un CFE"]]', 'Vérifiez que votre logiciel de facturation produit effectivement le type précis de CFE requis par votre transaction -- émettre un e-Ticket alors qu''une e-Factura était nécessaire, ou l''inverse, crée de réels problèmes de conformité.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Uruguay' AND cd.section = 'file_format' AND cd.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', 'Base légale et version du schéma', '[["Décret fondateur", "Decreto 36/012 (8 février 2012)"], ["Cadre opérationnel", "Resolución DGI 798/012 (8 mai 2012)"], ["Version actuelle du schéma", "Format CFE v25 / v25.1, selon la spécification technique publiée par la DGI"], ["Renvoi sanctionnateur", "Decreto 36/012, art. 17 -- applique le régime général de sanctions relatif à la documentation fiscale en Uruguay, et non un barème d''amendes propre au CFE"]]', NULL, NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Uruguay' AND cd.section = 'file_format' AND cd.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) SELECT lc.id, 'fr', 'Le flux du CFE', 'Une facture conforme suit cette séquence dans le cadre du régime CFE de la DGI :', 'Il ne s''agit pas d''un dédouanement strict facture par facture -- la DGI préautorise la numérotation, et non chaque document individuel en temps réel -- mais chaque CFE doit néanmoins parvenir à la DGI et réussir ses contrôles pour constituer un document fiscal valable.' FROM deep_dive_lifecycle_cards lc JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Uruguay';
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT st.id, 'fr', 'L''émetteur demande à la DGI une plage numérotée (CAE), valable deux ans' FROM deep_dive_lifecycle_statuses_v2 st JOIN deep_dive_lifecycle_cards lc ON st.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Uruguay' AND st.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT st.id, 'fr', 'La facture est générée en XML signé, à l''aide d''un numéro autorisé de cette plage' FROM deep_dive_lifecycle_statuses_v2 st JOIN deep_dive_lifecycle_cards lc ON st.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Uruguay' AND st.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT st.id, 'fr', 'Le CFE est transmis à la DGI, qui effectue la validation structurelle/formelle' FROM deep_dive_lifecycle_statuses_v2 st JOIN deep_dive_lifecycle_cards lc ON st.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Uruguay' AND st.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT st.id, 'fr', 'Le CFE est remis au destinataire, avec un code QR pour vérification publique' FROM deep_dive_lifecycle_statuses_v2 st JOIN deep_dive_lifecycle_cards lc ON st.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Uruguay' AND st.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT st.id, 'fr', 'Le document reste soumis au contrôle ultérieur de cohérence et d''audit de la DGI' FROM deep_dive_lifecycle_statuses_v2 st JOIN deep_dive_lifecycle_cards lc ON st.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Uruguay' AND st.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', 'Ce que la loi exige', '[["Decreto 36/012 (2012)", "Décret fondateur créant le régime CFE"], ["Resolución 798/012 (2012)", "Cadre technique/opérationnel"], ["Déploiement par étapes selon la tranche de chiffre d''affaires (2014-2019)", "D''abord les grands contribuables, les contribuables plus petits ajoutés lors de vagues annuelles ultérieures"], ["Resolución 2548/023 (2023)", "A fixé l''échéance finale du 31 décembre 2024 pour la population de contribuables restante"]]', 'Il s''agit du calendrier légal -- voir la carte suivante pour savoir précisément qui est couvert depuis l''obligation universelle de janvier 2025.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Uruguay' AND cd.section = 'scope_transmission' AND cd.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', 'Qui reste exempté après l''obligation universelle de janvier 2025', '[["Petite agriculture", "Activité exclusivement agricole, revenu annuel inférieur à UI 4 000 000"], ["Construction à valeur ajoutée", "Assujettis à la TVA n''exerçant que des services de construction à valeur ajoutée sur des biens immobiliers"], ["Contribuables IRNR", "Contribuables de l''impôt sur le revenu des non-résidents"], ["Activité entièrement exonérée de TVA", "Sauf les utilisateurs directs/indirects des zones franches, qui restent couverts"], ["Régimes simplifiés de micro-entreprises", "Participants au Monotributo, au Monotributo Social MIDES et à l''Aporte Único"]]', 'Cette liste reflète l''annonce de la DGI elle-même du 28 novembre 2024 -- si vous n''êtes pas certain qu''une exemption s''applique encore à votre entreprise, confirmez-le directement auprès de la DGI plutôt que de présumer qu''une ancienne dérogation a survécu à la clôture de janvier 2025.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Uruguay' AND cd.section = 'scope_transmission' AND cd.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', '⚖️ L''Uruguay ne fixe pas d''amendes spécifiques au CFE', NULL, NULL, 'Le Decreto 36/012, art. 17, indique explicitement que le non-respect des règles relatives au CFE est sanctionné selon le régime général de sanctions applicable à la documentation fiscale en Uruguay, et non par un barème d''amendes dédié à la facturation électronique. Ce régime figure dans le Código Tributario (Ley 14.306, 1974) -- ce sont les dispositions ci-dessous qui régissent réellement l''exposition, et non les montants ronds en pesos parfois diffusés dans des contenus de fournisseurs, que cette page ne reprend délibérément pas car ils n''ont pu être rattachés à une source vérifiable.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Uruguay' AND cd.section = 'penalties_related' AND cd.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', '📋 Non-conformité formelle et impôt sous-déclaré', NULL, NULL, 'L''article 95 du Código Tributario régit la ''contravención'' -- la violation d''obligations formelles, y compris l''obligation d''émettre correctement le CFE -- avec une amende fixée dans le texte du code lui-même ; il n''a pas été possible de confirmer indépendamment si ce montant a été actualisé administrativement depuis la rédaction de la loi de 1974, il convient donc de traiter avec prudence tout montant précis en pesos cité ailleurs. Par ailleurs, l''article 97 traite de l''« omisión de pago » : lorsque des irrégularités liées au CFE entraînent une sous-déclaration de la TVA ou de l''IRAE, l''amende s''élève de une à cinq fois le montant de l''impôt éludé.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Uruguay' AND cd.section = 'penalties_related' AND cd.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', '🔒 Conséquences pratiques au-delà d''une amende', NULL, NULL, 'Un CFE rejeté ou jamais correctement émis est traité comme si aucune facture n''existait -- le destinataire perd la possibilité de déduire la dépense ou de réclamer le crédit de TVA associé. Plusieurs sources de la pratique lient également la non-conformité grave ou répétée au risque que la DGI suspende le Certificado Único du contribuable, le certificat général de conformité fiscale exigé pour les marchés publics, le crédit bancaire et de nombreuses transactions commerciales -- bien qu''aucune règle codifiée unique établissant qu''un défaut lié au CFE déclenche automatiquement cette suspension n''ait pu être confirmée ; il convient donc de le considérer comme un risque pratique réel plutôt que comme une conséquence juridique automatique.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Uruguay' AND cd.section = 'penalties_related' AND cd.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', '🚨 La fraude par dol constitue une infraction pénale', NULL, NULL, 'L''article 110 du Código Tributario érige la ''defraudación tributaria'' -- l''utilisation de manœuvres frauduleuses pour obtenir un avantage indu aux dépens de l''État -- en infraction pénale, punie de six mois à six ans d''emprisonnement. Les poursuites exigent que la DGI elle-même dépose une plainte formelle et motivée ; cela est réservé aux cas de fraude véritable, et non à la non-conformité formelle habituelle.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Uruguay' AND cd.section = 'penalties_related' AND cd.sort_order = 3;

INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT pr.id, 'fr', 'Non-conformité formelle aux obligations d''émission du CFE (Código Tributario, art. 95 -- « contravención »)', 'Une amende fixée selon le barème général de contravención de l''art. 95 -- confirmez le montant actuellement applicable auprès de la DGI ou d''un conseiller fiscal uruguayen plutôt que de vous fier à un chiffre non vérifié', '—' FROM deep_dive_penalty_rows pr JOIN countries c ON pr.country_id = c.id WHERE c.name_en = 'Uruguay' AND pr.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT pr.id, 'fr', 'Sous-déclaration de la TVA/de l''IRAE résultant d''irrégularités liées au CFE (Código Tributario, art. 97 -- « omisión de pago »)', '1 à 5 fois le montant de l''impôt éludé', '—' FROM deep_dive_penalty_rows pr JOIN countries c ON pr.country_id = c.id WHERE c.name_en = 'Uruguay' AND pr.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT pr.id, 'fr', 'Fraude fiscale par dol (Código Tributario, art. 110 -- « defraudación tributaria »)', '6 mois à 6 ans d''emprisonnement ; nécessite une plainte formelle de la DGI', '—' FROM deep_dive_penalty_rows pr JOIN countries c ON pr.country_id = c.id WHERE c.name_en = 'Uruguay' AND pr.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'fr', 'Vérifiez si votre entreprise est déjà tenue d''émettre des CFE', 'Vérifiez si vous avez été inclus dans une vague antérieure par tranche de chiffre d''affaires (2014-2019) ou si vous n''êtes entré dans le champ d''application qu''avec l''obligation universelle de janvier 2025 -- et confirmez que vous ne relevez pas de l''une des rares exemptions restantes.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Uruguay' AND sp.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'fr', 'Enregistrez-vous auprès de la DGI en tant qu''émetteur électronique et obtenez un certificat valide', 'Vous aurez besoin d''un certificat électronique accrédité pour signer vos CFE, et devrez demander à la DGI votre première plage numérotée (CAE) avant de pouvoir émettre des documents conformes.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Uruguay' AND sp.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'fr', 'Choisissez le bon type de CFE pour chaque transaction', 'Utilisez l''e-Factura pour les ventes B2B, l''e-Ticket pour le commerce de détail/B2C, et les types de documents correspondants pour l''exportation, le bon de livraison ou la retenue à la source, le cas échéant -- émettre le mauvais type crée de réels problèmes de conformité.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Uruguay' AND sp.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'fr', 'Intégrez la génération XML, la signature numérique et la transmission à la DGI dans votre système de facturation', 'Vérifiez que votre logiciel produit réellement un XML de CFE conforme et signé, et le transmet à la DGI -- ne vous fiez pas à un processus manuel ou par lots qui pourrait prendre du retard sur les exigences de numérotation et de validation de la DGI.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Uruguay' AND sp.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'fr', 'Suivez votre plage de CAE et demandez-en une nouvelle avant épuisement', 'Une plage de CAE est valable deux ans et doit être demandée par lots d''au moins 100 numéros -- l''épuiser en pleine activité vous empêcherait d''émettre des factures conformes.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Uruguay' AND sp.sort_order = 4;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'fr', 'Vérifiez que votre logiciel ou votre prestataire est certifié pour la version actuelle du schéma CFE', 'La DGI révise périodiquement la spécification technique du CFE -- le plus récemment vers la v25.1, avec de nouveaux contrôles obligatoires à compter du 15 avril 2026 -- interrogez donc directement votre prestataire plutôt que de présumer d''une compatibilité continue.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Uruguay' AND sp.sort_order = 5;

INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT pt.id, 'fr', 'DGI e-Factura — le portail officiel du CFE, spécifications techniques et outil public de vérification des factures' FROM deep_dive_portals pt JOIN countries c ON pt.country_id = c.id WHERE c.name_en = 'Uruguay' AND pt.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT pt.id, 'fr', 'Dirección General Impositiva (DGI) — page institutionnelle consacrée à la Facturación Electrónica, annonces et résolutions officielles' FROM deep_dive_portals pt JOIN countries c ON pt.country_id = c.id WHERE c.name_en = 'Uruguay' AND pt.sort_order = 1;
